param([switch]$Apply)
$ErrorActionPreference='Stop';$root=[System.IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$targets=Get-ChildItem -LiteralPath $root -Directory -Recurse -Force -ErrorAction SilentlyContinue|Where-Object{$_.Name -in @('.cache','.tmp','__pycache__')};$quarantine=[System.IO.Path]::GetFullPath((Join-Path $root ('reports\autonomy-quarantine\'+(Get-Date -Format 'yyyyMMddTHHmmssZ'))));$actions=@();foreach($target in $targets){$resolved=[System.IO.Path]::GetFullPath($target.FullName);if(-not $resolved.StartsWith($root+[System.IO.Path]::DirectorySeparatorChar,[System.StringComparison]::OrdinalIgnoreCase)){throw 'Reset target escaped repository.'};$actions += [ordered]@{target=$resolved;action=$(if($Apply){'quarantine'}else{'would-quarantine'})};if($Apply){New-Item -ItemType Directory -Path $quarantine -Force|Out-Null;$destination=Join-Path $quarantine (([guid]::NewGuid().ToString('N'))+'-'+$target.Name);Move-Item -LiteralPath $resolved -Destination $destination}};[ordered]@{schemaVersion=1;applied=[bool]$Apply;destructiveDelete=$false;actions=$actions;generatedAt=(Get-Date).ToUniversalTime().ToString('o')}|ConvertTo-Json -Depth 6 -Compress
